#pragma GCC optimize("O3")
#pragma GCC target("avx2")
#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cmath>
using namespace std;

typedef long long ll;
const ll MOD = 1000000007LL;

ll mod_pow(ll base, ll exp) {
    ll result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int N, M;
ll probability[(1<<20)], probability2[(1<<20)];
ll probs[10][10];
int reverse_index[(1<<20)], reverse_index2[(1<<20)];

void enumerate_subsets(int step, vector<int>& current, ll prob) {
    if (step == M) {
        int next_id = 0, mask = 0;
        for (int j = 0; j < (1<<N); j++) {
            if (__builtin_popcount(j) != M) continue;
            vector<int> selected;
            for (int i = 0; i < N; i++) 
                if ((j >> i) & 1) selected.push_back(i);
            sort(selected.begin(), selected.end());
            bool found = false;
            do {
                bool ok = true;
                for (int idx = 0; idx < M; idx++) 
                    if (!((current[idx] >> selected[idx]) & 1)) { ok = false; break; }
                if (ok) { found = true; break; }
            } while (next_permutation(selected.begin(), selected.end()));
            if (found) mask |= (1 << next_id);
            next_id++;
        }
        probability[mask] = (probability[mask] + prob) % MOD;
        return;
    }

    for (int j = 0; j < (1<<N); j++) {
        current.push_back(j);
        ll new_prob = prob;
        for (int k = 0; k < N; k++) {
            if ((j >> k) & 1) 
                new_prob = (new_prob * probs[step][k]) % MOD;
            else 
                new_prob = (new_prob * (MOD + 1 - probs[step][k])) % MOD;
        }
        enumerate_subsets(step + 1, current, new_prob);
        current.pop_back();
    }
}

void enumerate_complement(int step, vector<int>& current, ll prob) {
    if (step == N) {
        int next_id = 0, mask = 0;
        for (int j = 0; j < (1<<N); j++) {
            if (__builtin_popcount(j) != N - M) continue;
            vector<int> selected;
            for (int i = 0; i < N; i++) 
                if ((j >> i) & 1) selected.push_back(i);
            sort(selected.begin(), selected.end());
            bool found = false;
            do {
                bool ok = true;
                for (int idx = 0; idx < N - M; idx++) 
                    if (!((current[idx] >> selected[idx]) & 1)) { ok = false; break; }
                if (ok) { found = true; break; }
            } while (next_permutation(selected.begin(), selected.end()));
            if (found) mask |= (1 << next_id);
            next_id++;
        }
        probability2[mask] = (probability2[mask] + prob) % MOD;
        return;
    }

    for (int j = 0; j < (1<<N); j++) {
        current.push_back(j);
        ll new_prob = prob;
        for (int k = 0; k < N; k++) {
            if ((j >> k) & 1) 
                new_prob = (new_prob * probs[step][k]) % MOD;
            else 
                new_prob = (new_prob * (MOD + 1 - probs[step][k])) % MOD;
        }
        enumerate_complement(step + 1, current, new_prob);
        current.pop_back();
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> N;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int val; cin >> val;
            probs[i][j] = (ll(val) * mod_pow(100LL, MOD-2)) % MOD;
            if (probs[i][j] < 0) probs[i][j] += MOD;
        }
    }

    if (N == 1) {
        cout << probs[0][0] << '\n';
        return 0;
    }

    M = N / 2;
    vector<int> temp;
    enumerate_subsets(0, temp, 1);

    for (int i = 0; i < (1<<20); i++) 
        probability[i] %= MOD;

    for (int i = 0; i < 20; i++) {
        for (int j = 0; j < (1<<20); j++) {
            if ((j >> i) & 1) {
                probability[j] = (probability[j] + probability[j ^ (1<<i)]) % MOD;
            }
        }
    }

    ll total = probability[(1<<20)-1];

    temp.clear();
    enumerate_complement(M, temp, 1);

    for (int i = 0; i < (1<<20); i++) 
        probability2[i] %= MOD;

    memset(reverse_index, -1, sizeof(reverse_index));
    int counter = 0;
    for (int i = 0; i < (1<<N); i++) {
        if (__builtin_popcount(i) != M) continue;
        reverse_index[i] = counter++;
    }

    memset(reverse_index2, -1, sizeof(reverse_index2));
    counter = 0;
    int corr[25] = {};
    for (int i = 0; i < (1<<N); i++) {
        if (__builtin_popcount(i) != N - M) continue;
        corr[counter] = reverse_index[(1<<N) - 1 - i];
        reverse_index2[i] = counter++;
    }

    ll result = 0;
    for (int i = 0; i < (1<<counter); i++) {
        ll cur = probability2[i];
        int mask = 0;
        for (int j = 0; j < counter; j++) {
            if ((i >> j) & 1);
            else mask += (1 << corr[j]);
        }
        result = (result + cur * ((total - probability[mask] + MOD) % MOD)) % MOD;
    }

    cout << result << '\n';
    return 0;
}
